-- MAGIC     <tr>
-- MAGIC       <td>In-Place Migration</td>
-- MAGIC       <td>Upgrade in same workspace</td>
-- MAGIC       <td>Fast, all-in-one</td>
-- MAGIC       <td>Some downtime; one-shot cutover</td>
-- MAGIC       <td>Small/simple workloads</td>
-- MAGIC     </tr>
-- MAGIC     <tr>
-- MAGIC       <td>Parallel Migration</td>
-- MAGIC       <td>New UC workspace, gradual migration</td>
-- MAGIC       <td>No downtime; phased</td>
-- MAGIC       <td>More effort to sync/validate</td>
-- MAGIC       <td>Large/complex environments</td>
-- MAGIC     </tr>
-- MAGIC     <tr>
-- MAGIC       <td>HMS Federation</td>
-- MAGIC       <td>Federate HMS into UC, mirror assets</td>
-- MAGIC       <td>Zero code/data change</td>
-- MAGIC       <td>Not full migration; hybrid only</td>
-- MAGIC       <td>Hybrid/adoption bridge, incremental</td>
